const tasks = [{ id: 'a', left: 5 }, { id: 'b', left: 2 }, { id: 'c', left: 8 }];
const q = 3;
const done = [];
let t = 0, i = 0;
while (tasks.some(x => x.left > 0)) {
  const task = tasks[i % tasks.length];
  if (task.left > 0) {
    const used = Math.min(q, task.left);
    task.left -= used;
    t += used;
    if (task.left === 0) done.push(task.id + t);
  }
  i++;
}
console.log(done.join('-') + '|' + t + '|' + i);
